2	import { InvoiceRow } from '../../slots/defs/invoiceRow';
3	import { invoicesKey, listInvoices, payInvoice, type Invoice } from './api';
4	
5	// Mark an invoice paid — one new file filling the per-invoice-row action slot. Payment is the last
6	// step of the DRAFT -> SENT -> PAID lifecycle, so the button only appears once the invoice has been
7	// SENT: the slot queries ['invoices', projectId] for its OWN row's status rather than being handed
8	// it. The click is a useMutation (never a hand-rolled status flip in state); on success we invalidate
9	// the project's ['invoices', projectId] key so the invoices panel refetches the new status. The
10	// server also appends the audit record, so "keep a record every time" is handled where the
11	// side-effect lives.
12	function PayInvoice({ invoiceId, projectId }: { invoiceId: number; projectId: number }) {
13	  const queryClient = useQueryClient();
14	  const { data: invoices } = useQuery({
15	    queryKey: invoicesKey(projectId),
16	    queryFn: () => listInvoices(projectId),
17	  });
18	  const mutation = useMutation({
19	    mutationFn: () => payInvoice(invoiceId),
20	    onSuccess: () => {
21	      void queryClient.invalidateQueries({ queryKey: invoicesKey(projectId) });
22	    },
23	  });
24	
25	  const invoice = invoices?.find((i: Invoice) => i.id === invoiceId);
26	  if (!invoice || invoice.status !== 'SENT') {
27	    return null;
28	  }
29	
30	  return (
31	    <button
32	      data-testid={`invoice-pay-${invoiceId}`}
33	      type="button"
34	      disabled={mutation.isPending}
35	      onClick={() => mutation.mutate()}
36	    >
37	      Mark paid
38	    </button>
39	  );
40	}
41	
42	export const contribution = InvoiceRow.fill({ order: 0, Component: PayInvoice });
